import{_ as a,c as t,o as r,al as s}from"./chunks/framework.QMC68jD7.js";const h=JSON.parse('{"title":"1. 什么是Redux","description":"","frontmatter":{},"headers":[],"relativePath":"tech/React/11-只背-不讲-redux状态管理.md","filePath":"tech/React/11-只背-不讲-redux状态管理.md","lastUpdated":1777271852000}'),n={name:"tech/React/11-只背-不讲-redux状态管理.md"};function i(l,e,d,o,c,p){return r(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="_1-什么是redux" tabindex="-1">1. 什么是Redux <a class="header-anchor" href="#_1-什么是redux" aria-label="Permalink to &quot;1. 什么是Redux&quot;">​</a></h1><p>redux 是一个独立专门用于做状态管理的 JS 库(不是 react 插件库)</p><h1 id="_2-为什么使用redux" tabindex="-1">2. 为什么使用Redux <a class="header-anchor" href="#_2-为什么使用redux" aria-label="Permalink to &quot;2. 为什么使用Redux&quot;">​</a></h1><ul><li><p>因为对于react来说，同级组件之间的通信尤为麻烦，或者是非常麻烦了，所以我们把所有需要多个组件使用的state拿出来，整合到顶部容器，进行分发。</p></li><li><p>首先明确一点，Redux 是一个有用的架构，但不是非用不可。事实上，大多数情况，你可以不用它，只用 React 就够了</p></li></ul><h1 id="_3-redux的应用场景" tabindex="-1">3. Redux的应用场景 <a class="header-anchor" href="#_3-redux的应用场景" aria-label="Permalink to &quot;3. Redux的应用场景&quot;">​</a></h1><p>从组件角度看，如果你的应用有以下场景，可以考虑使用 Redux。</p><ul><li>某个组件的状态，需要共享</li><li>某个状态需要在任何地方都可以拿到</li><li>一个组件需要改变全局状态</li><li>一个组件需要改变另一个组件的状态</li></ul><h1 id="_4-面试题-redux的三个核心概念" tabindex="-1">4. 面试题：Redux的三个核心概念 <a class="header-anchor" href="#_4-面试题-redux的三个核心概念" aria-label="Permalink to &quot;4. 面试题：Redux的三个核心概念&quot;">​</a></h1><h2 id="_4-1-store" tabindex="-1">4.1 store <a class="header-anchor" href="#_4-1-store" aria-label="Permalink to &quot;4.1 store&quot;">​</a></h2><p>Redux的核心是store，它由Redux提供的 createStore(reducer) 这个方法生成</p><p>三个相关API:</p><p>store.getState()：在组件中获取存储的store数据；</p><p>store.dispatch(action)：分发action，并返回一个action，这是唯一能改变store中数据的方式；</p><p>subscribe(listener)：注册(订阅)一个监听者，store发生变化的时候被调用。</p><h2 id="_4-2-reducer" tabindex="-1">4.2 reducer <a class="header-anchor" href="#_4-2-reducer" aria-label="Permalink to &quot;4.2  reducer&quot;">​</a></h2><p>reducer是一个纯函数，它根据previousState和action计算出新的state。指定了应用状态的变化如何响应action并发送到store的。 reducer(previousState,action)</p><h2 id="_4-3-action" tabindex="-1">4.3 action <a class="header-anchor" href="#_4-3-action" aria-label="Permalink to &quot;4.3  action&quot;">​</a></h2><p>action本质上是一个JavaScript对象，其中必须包含一个type字段来表示将要执行的动作，其他的字段都可以根据需求来自定义。数据的唯一来源，描述了有事情发生这一事实。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const ADD_TODO = &#39;ADD_TODO&#39;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  type: ADD_TODO,</span></span>
<span class="line"><span>  value: &#39;数据&#39;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h1 id="_5-面试题-redux的工作流程" tabindex="-1">5. 面试题：Redux的工作流程 <a class="header-anchor" href="#_5-面试题-redux的工作流程" aria-label="Permalink to &quot;5. 面试题：Redux的工作流程&quot;">​</a></h1><ol><li>用户在UI组件中通过 store.dispatch触发action ；</li><li>store 自动调用reducer，并传入之前的state，以及用户的action， 经过reducer返回新的state；</li><li>组件通过store.subscribe(listener) 订阅state的变化，可通过setState更新react UI。</li></ol>`,21)])])}const _=a(n,[["render",i]]);export{h as __pageData,_ as default};
